"""Build a standalone founder-facing explanation from reviewed project evidence."""
import base64
import html
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


# Render a compact comparison table with intentional authored HTML in its cells.
def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{cell}</th>' for cell in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{cell}</td>' for cell in row)+'</tr>' for row in rows)+'</tbody></table></div>'


# Wrap each chapter with a stable navigation anchor and visible chapter number.
def chapter(identifier, number, title, body):
    return f'<section id="{identifier}"><div class="eyebrow chapter-number">CHAPTER {number}</div><h2>{title}</h2>{body}</section>'


# Generate a self-contained HTML document with no external fonts, scripts or images.
def main():
    guide=(ROOT/'app/static/flow-guide.html').read_text(encoding='utf-8')
    architecture=re.search(r'<svg viewBox="0 0 940 430".*?</svg>',guide,re.S).group()
    sections=[]
    sections.append(chapter('problem','01','The problem we are solving', '''
    <p class="intro">Eluno needs a better billing experience in its stores while keeping Shopify as the official record of customers, products, inventory, orders, recorded payments and refunds.</p>
    <p>The assignment describes seven Bengaluru stores. Staff already use an internal store tool for queues and prescriptions, but billing happens in Shopify POS. The problem is the gap between those systems and the store’s daily work.</p>
    <div class="cards three"><article><h3>At the counter</h3><p>Staff need quick billing, correct offers, customer flags and one bill for a family. Manual work makes the experience inconsistent.</p></article><article><h3>After the sale</h3><p>A wrong lens creates a remake. A return can put stock in the wrong location. A lost response can tempt staff to charge twice.</p></article><article><h3>At day-end</h3><p>Finance needs correct tax, traceable invoices, recorded drawer expenses and numbers that agree with Shopify. Leadership needs the whole day’s performance.</p></article></div>
    <div class="say"><span>Explain it this way</span><p>“We are building the billing layer between the store team and Shopify. It brings the customer, prescription, product, payment and reporting steps into one controlled process.”</p></div>
    <h3>What success means</h3><ul><li>A valid bill produces one payment attempt and one recorded source order, with exact amounts and traceable references.</li><li>An invalid lens or insufficient stock is caught before payment.</li><li>A full return reverses the original money and tax, and restores the frame to the right store.</li><li>Staff and leadership can explain the result using the same source records.</li></ul>
    <p class="muted">These are acceptance goals. We have not measured a reduction in remakes, conversion improvement or live-store time savings. Those business outcomes need a pilot.</p>
    '''))
    sections.append(chapter('breakdown','02','How we broke down the request', '''
    <p>We separated the request into seven required flows, additional store tools, unresolved business decisions and work owned by other systems. This kept the core financial journey visible as the demo expanded.</p>
    '''+table(['Workstream','Problem to solve','Our response'],[
      ('Customer and clinical','Who is buying, who wears each pair, and is the lens valid?','Find the source customer; read prescriptions; validate each wearer and selected lens.'),
      ('Pricing and documents','Which offers apply, what is the tax, and which invoice number is used?','Use configured offer/rate data, integer-paise calculations and a separate store invoice sequence.'),
      ('Payment and source order','How does a paid bill reach Shopify without a blind duplicate?','Save the quote and operation state; charge; create the source order; retain both references.'),
      ('Return and remake','How do we reverse a sale or replace only a lens?','Full source refund with original tax/location; separate lens-only remake flow.'),
      ('Access and audit','Who may sell, discount, refund or author prescriptions?','Enforce role and store permissions in the API, with authenticated identity and audit records.'),
      ('Daily operations','How do we close cash and explain all-store results?','Drawer sessions, expenses, source reports, combined daily summary and notification outbox.'),
      ('Recovery and handoff','How do we demonstrate correctness and handle unknown outcomes?','Durable states, isolated tests, browser checks, Swagger walkthrough and submission documentation.')
    ])+'''
    <div class="cards two"><article><span class="tag">Must: exercise baseline</span><ol><li>Customer and latest valid prescription.</li><li>Frame/lens cart with clinical validation.</li><li>Offers from the supplied configuration.</li><li>HSN-based inclusive GST.</li><li>Terminal charge, source order and store invoice.</li><li>Full refund with tax and inventory treatment.</li><li>Source-derived store/date day-end report.</li></ol></article><article><span class="tag amber">Expanded demo scope</span><p>We then included a visual frontend, five roles, family/multi-frame carts, printable documents, remakes, drawer expenses, channel reports, a combined leadership report and a formatted outbox.</p><p>The brief accepts an API or CLI; the frontend is a presentation and usability addition. Partial refunds, general paid-in cash events and the suggested AI stretch features are not delivered.</p></article></div>
    <h3>Conflicts we surfaced instead of hiding</h3>
    '''+table(['Request / conflict','Working decision','Who must confirm'],[
      ('Retail wants all offers to stack. Supplied rules include non-stackable offers.','Follow the supplied configuration; show applied/rejected decisions. Do not promise every named offer always combines.','Retail + Finance'),
      ('Retail wants instant manager discounts; Finance requires approval identity and reason.','A manager acts directly within the 10% limit, with identity and reason retained. No separate approval chain.','Retail + Finance'),
      ('Five-degree axis entry vs existing issued prescriptions.','Use five-degree steps for new manual entries. Preserve already-issued source values and validate them.','Optometry'),
      ('No invoice gaps vs abandoned bills.','Retain reserved, issued and cancelled allocations. Never silently recycle an invoice number.','Finance'),
      ('Under 10 seconds and all stores live by 15 Nov.','Treat as measured rollout gates. Local timing is not a production service guarantee.','Founder + Product'),
      ('Beverage prompt and footfall camera repair.','Route to queue-tool owner and facilities/vendor respectively. Not part of this supplied POS code.','Product / facilities')
    ])))
    sections.append(chapter('execution','03','The steps we took to build it', '''
    <p>This is a reconstruction from the code, conversation and test evidence. It describes the work performed; it is not an invented sprint history, timesheet or proof that every activity happened in a strict order.</p>
    <ol class="timeline">
      <li><strong>Read the brief and stakeholder inputs.</strong><p>Extracted the seven Must flows, the store/finance/clinical conflicts and external dependencies. Prepared the stakeholder reply and recorded assumptions.</p></li>
      <li><strong>Inspected the supplied data and mocks.</strong><p>Identified seven stores plus HQ, source catalog/stock/customer records, store-tool prescriptions/staff and the payment terminal. The exercise explicitly permits these mocks.</p></li>
      <li><strong>Built business rules and local state.</strong><p>Created cart, prescription, lens, tax and discount logic; added saved quotes, state transitions and store invoice allocations in SQLite.</p></li>
      <li><strong>Connected the financial flow.</strong><p>Added source reads, terminal charge, paid source order, full refund and source-derived day-end report. Kept uncertain writes visible instead of automatically repeating them.</p></li>
      <li><strong>Added staff workflows and the two interfaces.</strong><p>Built login, roles, store boundaries, family billing, clinical entry, remakes, cash operations and the frontend. Swagger exposes the same backend process for a technical demonstration.</p></li>
      <li><strong>Tested the assumptions and fixed defects.</strong><p>The cashier review exposed the one-frame restriction. Tests also found malformed-request crashes, invalid money input and a cash-refund retry issue. We corrected them and checked the source effects.</p></li>
      <li><strong>Improved leadership visibility.</strong><p>The Reports page now starts with company-wide daily totals. Store rows are optional detail. The outbox now shows report tables, readable timestamps and honest delivery status.</p></li>
      <li><strong>Prepared the handoff.</strong><p>Added test plans, walkthroughs, architecture notes and recording guidance. The initial repository was pushed to GitHub. The latest report/outbox changes and this document remain local until another push.</p></li>
    </ol><div class="note"><strong>AI assistance:</strong> AI helped with implementation, tests, investigation and documentation. An early assisted design assumed one frame/lens pair per wearer; real cashier feedback and regression checks exposed that limitation. The code still needs human understanding, review and business sign-off. Do not describe AI-generated work as independently handwritten.</div>
    '''))

    tickets=[
      ('01','Scope & acceptance','Product / engineering','Must','Reviewed','Turn the stakeholder thread into Must scope, questions, exclusions and a runnable demonstration.','Named decision owners, explicit assumptions and a requirement-to-evidence checklist.','STAKEHOLDER_REPLY.md; docs/EXERCISE_MUST_AUDIT.md'),
      ('02','Source data adapters','Backend','Must','Implemented','Read source customer/catalog/location/stock and store-tool staff/prescriptions.','Selected records come from adapters; source prices are not trusted from browser input.','app/gateways/http.py; app/operations.py'),
      ('03','Cart & lens validation','Backend / clinical','Must','Tested','Validate wearer prescription against selected lens type, index, coating and limits.','Reject expired/out-of-range Rx or missing required ADD with a reason before charging.','app/services/prescriptions.py; tests/test_stage4.py'),
      ('04','Offer engine','Backend / finance','Must','Tested','Apply supplied date, condition, tag and stackability rules with explanations.','Repeatable discounts, capped allocations and no negative line total. Exact business stacking still needs agreement.','app/services/offers.py; tests/test_stage4.py'),
      ('05','Tax & invoice series','Backend / finance','Must','Tested','Split inclusive MRP into taxable/CGST/SGST and allocate per-store invoice numbers.','All line sums reconcile in paise; repeated requests and cancellations do not reuse numbers.','app/services/taxes.py; app/persistence/sqlite.py; tests/test_foundation.py'),
      ('06','Quote persistence','Backend','Must','Tested','Save the priced bill and expected source payload before payment.','Draft contains exact amount, invoice and offer decisions; no charge or order write at prepare.','app/services/sale.py; tests/test_stage5.py'),
      ('07','Payment → source order','Backend / integrations','Must','Tested','Capture payment then create the paid order, recording both references.','Source order includes lines, discounts, tax, transaction, Rx and location; tracked stock changes once.','app/services/sale.py; tests/test_stage5.py'),
      ('08','Full refund','Backend / finance / ops','Must','Tested','Verify original refund amount/tax, return money and record the source refund.','Frame restocks at original store; lens does not restock; credit note links to original invoice.','app/services/refunds.py; tests/test_stage6.py'),
      ('09','Store day-end report','Backend / finance','Must','Tested','Report source sales/refunds for store and day with the required money fields.','Bill count, gross, taxable, tax, discounts, refunds and payment split; reject incomplete capped results.','app/services/reporting.py; tests/test_stage6.py'),
      ('10','Login, roles & audit','Backend / security','Additional','Tested','Protect both UI and API with sessions, CSRF, role/store guards and identities.','Wrong role/store or spoofed staff is denied; sessions expire and revoke; five-role endpoint matrix passes.','app/security.py; app/web.py; tests/test_production_matrix.py'),
      ('11','Family & quantities','Frontend / backend','Additional','Tested','One bill for multiple wearers and multiple items; add/remove repeated units.','Wearer-specific Rx, aggregated stock demand and source unit lines preserved; no silent frame replacement.','app/static/app.js; app/services/sale.py; tests/test_cart_regressions.py'),
      ('12','Clinical entry & remakes','Clinical / backend','Additional','Implemented','Add validated local Rx records and lens-only remakes with cost ownership.','Company-funded remake tested; no new frame charge or stock movement. External cost recovery is only recorded.','app/web.py; tests/test_demo.py'),
      ('13','Cash drawer & alerts','Retail / finance / backend','Additional','Tested','Open float, record cash sales/refunds/expenses, close/count and flag variance.','Expected balance reconciles; abs variance above ₹200 queues alert; pending financial issues block close.','app/operations.py; tests/test_demo.py'),
      ('14','Frontend & Swagger','Frontend / backend','Additional','Tested','Make the same process explainable through staff screens or requests and schemas.','Browser journey and OpenAPI references checked; no separate financial rules in the frontend.','app/static/app.js; app/api_documentation.py; tests/test_api_documentation.py'),
      ('15','Combined daily leadership report','Frontend / finance','Additional','Browser checked','Lead with total sales, bill count, weighted average bill, net collections, discounts, tax and refunds.','Admin/finance see all seven stores combined; other roles stay scoped; empty date renders safely.','app/static/app.js; tests/test_browser_roles.py'),
      ('16','Report outbox & schedule','Backend / frontend','Additional','Partial','Queue a daily founder digest and finance variance alerts; make previews readable.','Durable daily key; table formatting; known delivery states. Real SMTP delivery and all clock boundaries remain unverified.','app/scheduler.py; app/operations.py; tests/test_release_boundaries.py'),
      ('17','Failure & retry protection','Backend / ops','Cross-cutting','Partial','Retain pending/uncertain states and reconcile source references without blind writes.','Lost-response and repeated-operation tests pass. Unknown terminal outcomes still require investigation.','app/persistence/sqlite.py; tests/test_stage5.py; tests/test_stage6.py'),
      ('18','Verification & handoff','Engineering / reviewer','Cross-cutting','Partial','Run isolated tests, document limits and provide reproducible setup, repo and video.','Initial repo pushed; prior full suite passed. Clean-clone review, final push, Loom and submission remain.','README.md; FINAL_AUDIT.md; LOOM_SCRIPT.md'),
      ('19','Live integration & pilot','Integrations / finance / ops','Next phase','Proposed','Connect real providers, approve policies/documents and run a controlled store pilot.','Measured latency, verified settlement, recovery drills, support ownership and rollout sign-off.','No production acceptance evidence yet')
    ]
    ticket_html=''
    for ident,title,owner,priority,status,work,accept,evidence in tickets:
        color='amber' if status in {'Partial','Proposed'} else ''
        ticket_html+=f'<details class="ticket" data-ticket data-priority="{priority}"><summary><span class="ticket-id">POS-{ident}</span><strong>{title}</strong><span class="tag {color}">{status}</span></summary><div class="ticket-meta">Workstream: {owner} · Scope: {priority}</div><p><b>Work:</b> {work}</p><p><b>Acceptance:</b> {accept}</p><p class="evidence"><b>Evidence:</b> {evidence}</p></details>'
    sections.append(chapter('tickets','04','Ticket division and acceptance criteria', '''
    <p>The following tickets organize the completed work and remaining work for discussion. <strong>These are retrospective documentation IDs, not existing Jira/GitHub issue IDs.</strong> Workstream labels describe responsibility areas; they do not claim that named teams were assigned or completed these tickets.</p>
    <div class="dependency">Scope → source reads → cart / Rx / offers / tax → saved quote → payment + order → refund + report → operational screens → verification</div>
    <div class="tools"><label for="ticket-search">Find a ticket</label><input id="ticket-search" type="search" placeholder="Search refund, Shopify, cash, test…"><label for="ticket-filter">Scope</label><select id="ticket-filter"><option value="">All work</option><option>Must</option><option>Additional</option><option>Cross-cutting</option><option>Next phase</option></select><button id="expand-tickets" type="button">Expand tickets</button></div><p class="muted" id="ticket-count" aria-live="polite"></p>
    '''+ticket_html))

    sections.append(chapter('architecture','05','Where the data comes from', '''
    <p>We do not read data from the Shopify POS screen. The backend calls Shopify-style APIs through an adapter. The exercise provides local versions of Shopify Admin, the store tool and a terminal. All records and payments in this demo are synthetic.</p><div class="diagram">'''+architecture+'''</div>
    <p class="muted">Arrows show requests from the backend; responses return on the same connection. A “mock” is a simulated external service used to exercise the real application flow without touching live customers or money.</p>
    '''+table(['Data / service','Owner in this demo','How we use it'],[
      ('Customer identity and priority/campaign tags','Shopify mock','Find the payer and show flags; use tags in eligibility rules. The bootstrap directory is a local search aid; the selected customer is fetched from the source.'),
      ('Products, variants, prices and HSN metadata','Shopify mock','Choose items and calculate from source values, not a browser-supplied selling price. A variant is one sellable product option.'),
      ('Store location and physical inventory','Shopify mock','Read available quantity at the billing store. Map stock movements and reports to the same location.'),
      ('Issued prescriptions and staff','Store-tool mock','Find the latest valid Rx and store staff authorization. Newly entered Rx records are a local clinical overlay, not a write back to Shopify.'),
      ('Offer definitions and effective-date tax rates','Supplied local JSON configuration','Apply deterministic pricing rules and configured HSN rates. This is not fetching Shopify’s discount engine.'),
      ('Electronic charge and refund','Terminal mock','Capture UPI/card money or refund the original captured charge. Separately record transactions in Shopify.'),
      ('Quotes, invoice series, users, operation state and outbox','SQLite in our app','Remember intended amounts, who acted, what was attempted and which source IDs were returned.'),
      ('Orders, recorded transactions and source refunds','Shopify mock','Write completed financial records, then read them back for evidence and reporting.')
    ])+'''<div class="note"><strong>Central data, controlled access:</strong> the seed includes MM, HSR, BR, KMG, JN, IN and VC, plus HQ/Lab as a warehouse. Cashier/manager/optometrist demo accounts are HSR-scoped. Admin and finance can review all seven. The customer/catalog directory is shared; transaction/inventory/report access is store-checked.</div>
    <p><strong>Boundary to revisit:</strong> domain models and pricing/clinical rules are independent of Shopify, but sale/refund orchestration still consumes and builds Shopify-shaped dictionaries. We have an explicit adapter, not complete provider independence. Moving all external mapping to the adapter would make future provider changes easier.</p>
    '''))
    sections.append(chapter('sale','06','The complete billing flow', '''
    <p class="intro">Example: an existing customer wants a frame and prescription lens at HSR. The cashier confirms the customer, adds the correct items, reviews the quote and accepts payment.</p>
    <div class="flow"><span>Identify</span><b>→</b><span>Validate</span><b>→</b><span>Price</span><b>→</b><span>Save quote</span><b>→</b><span>Charge</span><b>→</b><span>Write order</span><b>→</b><span>Read back</span></div>
    '''+table(['Step','What the system does','What exists after this step'],[
      ('1 · Sign in','Authenticate the user; check session, role, store ownership and CSRF on writes.','A known staff identity, not yet a bill.'),
      ('2 · Identify customer','Look up source customer by phone; read tags and latest valid prescription from the store tool.','The payer, wearer/Rx and relevant customer flags.'),
      ('3 · Select items','Cashier chooses source variant IDs for each wearer. Repeated IDs represent units; frames/lenses pair in their selection order per wearer.','A draft cart. Up to ten wearers and thirty units each in this demo.'),
      ('4 · Validate','Backend fetches variants, staff and location; checks combined stock demand, Rx expiry and lens compatibility.','Either a clear rejection before payment, or a valid cart.'),
      ('5 · Calculate and save','Evaluate configured offers; split inclusive GST per line; reserve store invoice number; save immutable quote and prepared order payload.','checkout_id, invoice_no, total_paise, tax_paise, offer decisions and draft state. No payment, order or stock reservation yet.'),
      ('6 · Confirm','Reload the saved quote and recheck stock. Persist pending payment reference before attempting the terminal charge.','Captured charge reference if successful, or an uncertain state to investigate. Cash needs an open drawer and bypasses the electronic terminal.'),
      ('7 · Write the source order','Add successful payment transaction to the saved payload; POST the paid order. The source applies tracked inventory decrement.','Source order ID linked to our checkout, order_recorded state and issued invoice.'),
      ('8 · Show proof','Fetch the actual source order; display invoice, payment reference, tax/discount lines and later refunds.','Evidence that the bill reached the source, not merely a successful local calculation.'),
      ('9 · Include in reports','Read source orders and transactions for the selected day and stores.','Store report and combined leadership totals. No separate copy of the sales ledger is used as final proof.')
    ])+'''
    <h3>What goes back into Shopify?</h3><div class="cards two"><article><h3>The items and amount</h3><ul><li>Customer and billing location IDs.</li><li>Variants, quantities and inclusive prices.</li><li>Discount applications and line allocations.</li><li>Tax lines and lens Rx / wearer properties.</li></ul></article><article><h3>The audit trail</h3><ul><li>Successful sale transaction and charge reference.</li><li>Our checkout ID and store invoice number.</li><li>Store, staff, channel and payment method.</li><li>Manager reason/approver or remake reference where relevant.</li></ul></article></div>
    <div class="say"><span>Explain it this way</span><p>“Fetching the customer is just the start. We validate and price the bill, save it, accept payment, write the paid order back, and then read the order again to prove it is there.”</p></div>
    <p><strong>Three different IDs:</strong> the checkout ID tracks our operation; the payment charge ID tracks money at the terminal; the Shopify order ID tracks the source sale. The store invoice number is another separate reference. These must not be confused.</p>
    '''))

    sections.append(chapter('money','07','A worked example: money and stock', '''
    <p>These are deliberately simple illustrative values, not fixture prices or a statement of current tax law. Assume both lines have a configured 18% GST rate and an eligible 10% discount.</p>
    <div class="cards three"><article><span class="eyebrow">Inclusive MRP</span><div class="big">₹10,000</div><p>₹6,000 frame + ₹4,000 lens.</p></article><article><span class="eyebrow">Discount</span><div class="big">₹1,000</div><p>₹600 frame + ₹400 lens.</p></article><article><span class="eyebrow">Customer pays</span><div class="big">₹9,000</div><p>Stored as 900,000 paise.</p></article></div>
    '''+table(['Line','After discount','Taxable value','CGST','SGST'],[
      ('Frame','₹5,400.00','₹4,576.27','₹411.87','₹411.86'),('Lens','₹3,600.00','₹3,050.85','₹274.58','₹274.57'),('<strong>Total</strong>','<strong>₹9,000.00</strong>','<strong>₹7,627.12</strong>','<strong>₹686.45</strong>','<strong>₹686.43</strong>')
    ])+'''<p>We calculate in integer paise and round each line. An odd tax paisa goes to CGST first; the remaining part goes to SGST. The exact rule is: <strong>taxable + CGST + SGST = discounted line total</strong>. GST is already inside MRP, so it is not added again.</p>
    <h3>Follow the same frame through inventory</h3><div class="flow"><span>Before selection<br><strong>3 units</strong></span><b>→</b><span>After quote<br><strong>3 units</strong></span><b>→</b><span>Order recorded<br><strong>2 units</strong></span><b>→</b><span>Full refund recorded<br><strong>3 units</strong></span></div><p>Stock changes when the source order/refund succeeds. A quote does not reserve stock. We recheck before payment, but that is not a distributed reservation against the website or another live selling channel.</p>
    '''))
    sections.append(chapter('after-sale','08','Returns, remakes and daily operations', '''
    <div class="cards two"><article><span class="tag">Full return</span><h3>Reverse money, tax and inventory</h3><ol><li>Manager selects the original recorded checkout and reason.</li><li>Read original source order; ask source to calculate refund.</li><li>Verify full amount and original tax.</li><li>Refund terminal money, or handle cash return.</li><li>Write source refund with original transaction and line references.</li><li>Restock the frame at the billing store; do not restock the lens.</li><li>Show linked credit-note evidence.</li></ol><p class="muted">A source refund record and a terminal refund are separate calls. Full refunds are implemented; partial returns are not.</p></article><article><span class="tag">Remake</span><h3>Replace a lens without rebilling the frame</h3><p>Link a new lens-only checkout to the original invoice and wearer. Retain the reason, approving identity, lab cost and who bears that cost.</p><p>For company/external-optometrist cost allocation, customer charge can be zero. Customer-funded work can require payment. No new frame line or frame stock movement is created.</p><p class="muted">An external optometrist’s liability is recorded; automatic recovery of money from that party is not implemented.</p></article><article><span class="tag">Cash drawer</span><h3>Make the closing count explainable</h3><p><strong>Opening float + cash sales − cash refunds − expenses = expected cash.</strong></p><p>Example: ₹2,000 float + ₹9,000 sales − ₹300 expenses = ₹10,700 expected. If the cashier counts ₹10,450, variance is −₹250. That exceeds the absolute ₹200 threshold, so the app queues a finance alert.</p><p class="muted">Pending financial exceptions block close. A queued alert is not evidence that finance received an email.</p></article><article><span class="tag">Access</span><h3>Give each role the right actions</h3><p>Cashier sells and records expenses. Manager handles overrides, returns, remakes and drawer close. Optometrist authors prescriptions. Finance sees cross-store reporting/audit/outbox. Admin has central access.</p><p class="muted">The API enforces permissions, not just hidden buttons. Store-scoped users cannot read another store’s checkout by guessing its ID.</p></article></div>
    <h3>The clinic and the lab are still separate systems</h3><p>This project validates billing choices and retains clinical/remake references. It does not replace the lab order-management system, QC, dispatch, the queue application or camera hardware. We should not present those as delivered modules.</p>
    '''))
    screenshot=ROOT/'runtime/screenshots/leadership-daily-report.png'
    image_html=''
    if screenshot.exists():
        image_html='<figure><img alt="Combined daily report showing all seven stores, total sales, bills, average bill, taxes and optional store detail" src="data:image/png;base64,'+base64.b64encode(screenshot.read_bytes()).decode()+'"><figcaption>Actual local browser-test capture using synthetic data for 6 October 2026. This is a static example, not live company performance.</figcaption></figure>'
    sections.append(chapter('leadership','09','What the founder can see', '''
    <p class="intro">The Daily reports page now leads with one company-wide figure, not seven separate store tables.</p>
    <p>Admin and finance see all seven stores combined for the chosen date. The page shows total sales, bills, average bill value, net collections, discounts, GST, taxable sales and refunds. Combined channel totals sit below; store rows are collapsed until needed.</p>
    '''+table(['Metric','Meaning'],[
      ('Total daily sales','Sum of source order totals for the date, after discounts and including GST, before subtracting refunds.'),
      ('Total bills','Number of qualifying source sales for the date.'),
      ('Average bill value','Combined sales divided by combined bill count. We do not average the seven store averages.'),
      ('Net collected','Successful sale payments for the day minus refunds issued that day, including returns of older bills. This is not bank settlement.'),
      ('Reconciliation difference','Successful recorded sale payments minus order totals. Individual store differences remain flagged even if they cancel out in the combined number.'),
      ('Channels','Sales value by walk-in, WhatsApp-booked or online pickup as recorded on the order.')
    ])+image_html+'''
    <h3>The outbox explains what has—and has not—been sent</h3><p>The founder digest is scheduled after 10:00 AM IST for yesterday, with catch-up after restart. The saved email contains bills, average bill and discounts by store. The outbox formats that text into readable cards and tables, with report date, creation time and intended audience.</p>
    <div class="cards three"><article><span class="tag amber">Queued</span><p>Prepared and saved. Not yet sent. Without SMTP configuration, it remains a preview.</p></article><article><span class="tag">SMTP accepted</span><p>The configured mail server accepted the message. This is not proof of inbox delivery or that someone read it.</p></article><article><span class="tag amber">Uncertain / sending</span><p>Outcome needs review. Do not automatically resend an uncertain message and risk duplicate notifications.</p></article></div>
    <p class="muted">This is daily reporting, not monthly trends or a custom date-range dashboard. Source reads are capped by the supplied mock; at 250 orders, reporting rejects the result instead of calling it complete.</p>
    '''))

    sections.append(chapter('decisions','10','The main engineering decisions—and why',table(['Decision','Reason','Trade-off or boundary'],[
      ('Keep Shopify as the record; replace the till','Finance and the website must continue to use the same backend.','We still need real-provider access and contract testing before production.'),
      ('Use FastAPI + SQLite + a buildless browser frontend','A small, runnable exercise with explicit endpoints and durable local state.','Single-worker design; not a proven horizontally scalable deployment.'),
      ('Use supplied mocks, not real accounts','The exercise explicitly provides them and requires no live Shopify account.','Successful mock behavior is not live integration certification.'),
      ('Use the same API for UI and Swagger','Staff and reviewers can demonstrate the same rules and records.','Swagger still requires authentication and CSRF for writes.'),
      ('Fetch prices/stock on the server','The browser should not decide authoritative amounts or availability.','Network calls add latency; no general background cache/sync is implemented.'),
      ('Keep offers/tax in data files','Ordinary rule and rate changes do not need changes to calculation code.','Configuration needs review, effective dates and policy approval.'),
      ('Use integer paise','Avoid binary floating-point errors in financial calculations.','Rounding and discount allocation rules must remain explicit and tested.'),
      ('Save a quote before payment','Separate reviewable calculation from financial side effects.','Invoice numbers can be reserved before issue; keep abandoned allocations visible.'),
      ('Persist state before external writes','A lost response must not erase the fact that a charge/order was attempted.','An unknown result may block automation and require a person to investigate.'),
      ('Retry supported safe reads, not financial writes blindly','A repeated GET is different from a second charge or order.','Availability may be reduced while an uncertain operation is resolved.'),
      ('Serialize mutations in one app worker','Protect local concurrent operations and make same-checkout retries predictable.','This is not cross-system inventory locking or multi-replica safety.'),
      ('Preserve original tax and location for refunds','Refunds must reverse the original bill and restock the correct store.','Full refunds only; partial return allocation is deferred.'),
      ('Give each family member their own selections and Rx','A single payer may buy for several wearers.','Frame/lens positional pairing and the 10-wearer/30-unit limits need product acceptance.'),
      ('Use source records for reports','A locally marked success is not enough for finance reconciliation.','Legacy order-day reporting and newer refund-event-date reporting have different, documented bases.'),
      ('Represent email delivery honestly','Queued text, SMTP acceptance and unknown delivery are different states.','Real SMTP configuration, monitoring and recipient verification remain.')
    ])+'''<div class="note"><strong>Why this is not “everything synchronized”:</strong> we coordinate reads and writes and retain references. There is no general two-way background synchronization engine or webhook pipeline. Payment success followed by an unknown order outcome is a real intermediate state, not something the UI can wish away.</div>'''))

    sections.append(chapter('failures','11','What happens when something goes wrong',table(['Scenario','Expected behavior','Proof / remaining limit'],[
      ('Customer has expired Rx or incompatible lens','Block preparation with a reason the staff can act on.','Clinical boundary tests; no charge should occur.'),
      ('Two family members want more units than store stock','Aggregate demand across wearers and reject excess quantity.','Quantity regression tests; source inventory is authoritative.'),
      ('Stock was available at quote time but is now gone','Recheck before accepting payment; return a conflict and leave the quote draft.','Stale-quote regression test.'),
      ('Same checkout completed twice','If already recorded, return the same result. Concurrent completion should produce one order.','Concurrent same-checkout browser/API scenario coverage; single-worker assumption.'),
      ('Terminal response lost after sending charge','Persist payment_uncertain; block another charge attempt.','Lost-response test; manual terminal investigation may be necessary.'),
      ('Paid order was created but reply was lost','Persist order_uncertain; search source by saved checkout reference and link a unique match.','Source reconciliation test. No matching order remains unresolved; no automatic compensation guarantee.'),
      ('Refund response lost','Retain terminal/source uncertain state; do not refund the money blindly again.','Refund uncertainty tests; source refund can be reconciled by marker.'),
      ('Store Wi-Fi drops','Keep local/server drafts and durable operation state. Inspect what stage completed.','Not fully offline billing; all network/crash points are not covered.'),
      ('Cashier tries to approve a manager discount','Deny at the API, even if someone manually sends the request.','Role, staff impersonation and CSRF tests.'),
      ('Email result is unknown','Show a reviewable delivery state/error, not a fake “delivered” label.','Simulated SMTP outcomes and UI error rendering tests.')
    ])+'''<div class="state-path"><code>draft</code> → <code>payment_pending</code> → <code>payment_captured</code> → <code>order_pending</code> → <code>order_recorded</code><p>Any uncertain external outcome leaves a durable exception state for investigation.</p></div>'''))

    sections.append(chapter('verification','12','How we checked the work', '''
    <p>We tested calculation rules, complete financial journeys, permissions and the actual browser. Tests use isolated temporary app databases and fresh mock processes so they do not alter the reviewer’s active demo.</p>
    <div class="cards three"><article><div class="big">313</div><h3>Earlier full-suite passes</h3><p>164.61 seconds; one third-party Starlette/httpx deprecation warning. This is a recorded run, not a live badge.</p></article><article><div class="big">35</div><h3>Must-tier recheck passes</h3><p>9.62 seconds. Rechecked core clinical/offer/tax, durable state, sale, refund and reporting evidence against the original brief.</p></article><article><div class="big">5 roles</div><h3>Latest browser journey</h3><p>The expanded browser test passed in 28.41 seconds, including combined daily totals and formatted outbox/error content.</p></article></div>
    <p class="muted">The full suite was not rerun after the latest report/outbox presentation changes. The targeted browser journey and JavaScript syntax check passed. Small final wording/scope-label edits had syntax verification. This document does not upgrade that evidence into a new full-suite result.</p>
    <h3>Examples of defects we found and corrected</h3>
    '''+table(['Finding','Correction'],[
      ('Second frame replaced the first; API allowed only two items per wearer.','Additive cart, quantity controls and expanded member-based input; source stock/refund checks.'),
      ('Malformed JSON shapes caused server errors in middleware.','Reject invalid shapes as client errors before accessing fields.'),
      ('Boolean money values and invalid discount values could pass or crash validation.','Strict integer money and bounded integer discount inputs.'),
      ('Stock could disappear after quote preparation.','Recheck aggregate demand before payment.'),
      ('A completed cash refund retry required a newly open drawer.','Apply drawer precondition to a prepared cash refund, not an already-recorded one.'),
      ('Standalone family items inherited another wearer’s lens constraints or pair treatment.','Assign pair references only to actual matched units within the same wearer.'),
      ('Leadership saw a store-first report; outbox looked like raw text.','Promote combined totals, collapse store detail, format report messages and show delivery evidence.')
    ])+'''<h3>What the tests do not prove</h3><ul><li>Production response time below ten seconds, seven-store rollout or real business impact.</li><li>Real Shopify/payment/SMTP correctness, live pagination, settlement or external inventory races.</li><li>Every input edge case, cross-process contention, every scheduler clock boundary, disaster recovery or backup restoration.</li><li>A clean repository-wide style audit, hosted CI success or a clean-machine clone/deployment check.</li></ul><p>Test inventory: 46 planned scenarios, 31 endpoint/action permission cases and 75 automated test functions are catalogued in the separate end-to-end guide. Parameterization produces the larger executed count. A planned case is not automatically a passed case.</p>
    '''))
    sections.append(chapter('next','13','What is ready—and the proposed next phase', '''
    <div class="cards two"><article><span class="tag">Ready to demonstrate locally</span><p>The seven Must flows against supplied mocks; frontend and Swagger; five-role access; family/multiple-item billing; documents, full refunds and company-funded remake example; cash operations; daily combined reports and readable outbox.</p><p>Initial code is on GitHub. Latest local reporting/UI work and this brief still need to be included in a new commit/push.</p></article><article><span class="tag amber">Not a production launch approval</span><p>No live provider integration, real email delivery proof, public deployment validation, seven-store pilot or production latency certification. The Loom and actual assignment reply still need to be completed.</p><p>For the exercise, the repo and an up-to-eight-minute Loom are required. A public hosted frontend is optional. The newer covering email gives 72 hours; use its receipt time to calculate the deadline.</p></article></div>
    <h3>Proposed rollout gates—not completed work</h3>
    '''+table(['Gate','Work needed','People / systems needed'],[
      ('1 · Agree the operating rules','Approve example bills for offer stacking, manager reasons, Rx handling, invoice/credit-note rules, remake cost ownership and date cutoffs.','Product, Retail, Finance, Optometry'),
      ('2 · Verify provider contracts','Connect real Shopify/store-tool/terminal accounts and mappings. Confirm statuses, retry/idempotency behavior, pagination, events and settlement.','Integration owners and provider access'),
      ('3 · Harden operations','Address adapter mapping, deployment/auth/secrets, monitoring, backups, restore drills, exceptions, true delivery and clean install. Test concurrency/latency.','Engineering and support'),
      ('4 · Pilot one store','Use trained staff and controlled reconciliations. Observe bill timing, clinical rejections, returns and cash close. Agree support and rollback procedure.','Retail manager, Finance, Optometry, Ops'),
      ('5 · Expand only after acceptance','Compare evidence with agreed gates; train remaining stores and schedule rollout.','Founder and Product with store sign-off')
    ])+'''<div class="say"><span>The decision to ask the founder for</span><p>“The demo proves the core workflow against the supplied services. I propose we approve the remaining business rules, verify real integrations and run one controlled store pilot before committing all seven stores.”</p></div>'''))
    sections.append(chapter('present','14','How to explain it in a meeting', '''
    <div class="talk-track"><h3>A simple opening</h3><p>“The problem is not only making a bill. It is making sure the correct customer, prescription, price, tax, payment and stock movement stay connected. I built an Eluno till layer that keeps Shopify as the source record and controls that full journey.”</p></div>
    '''+table(['What to show','What to say','What proves it'],[
      ('Source customer, Rx and stock','“These are existing source records. No sale has happened yet.”','Customer tags, prescription limits, variant and location IDs.'),
      ('Prepared quote','“We validated the cart and calculated offers and inclusive GST before payment.”','Draft checkout, invoice allocation, total and offer reasons.'),
      ('Completed sale and source detail','“The terminal charge came first; then we wrote the paid order back.”','Charge reference, actual source order, tax/discount/Rx properties and stock change.'),
      ('Full refund','“We reverse the original amount and tax, returning the frame only to the store that sold it.”','Source refund and before/after location inventory.'),
      ('Daily reports','“Leadership sees the company total first; store detail is optional.”','Combined metrics for chosen date, with source-backed definitions.'),
      ('Report outbox','“This is what is prepared for leadership or finance; the status tells us whether SMTP accepted it.”','Report table, timestamp, saved body and delivery state.'),
      ('Tests and limits','“We tested the financial rules and failures. These are the boundaries still needing a pilot.”','Recorded runs, regression cases and open-gate list.')
    ])+'''<p>Use <code>http://127.0.0.1:8001</code> for the app and <code>/docs</code> for Swagger while the local runner is active. Admin/finance see central reports. HSR cashier credentials demonstrate store restrictions. Do not show passwords during recording.</p>
    <details><summary>Technical appendix: exact API chain</summary>
    '''+table(['App entry point','External work / result'],[
      ('GET /api/bootstrap and /api/inventory; POST /api/customers','Source locations/products, customers/search, inventory_levels; store-tool prescriptions/staff.'),
      ('POST /sales/prepare','Read source records; validate; calculate; save quote/invoice locally. No terminal charge or source order POST.'),
      ('POST /sales/{checkout_id}/complete','POST /terminal/charges for UPI/card, then POST source orders.json with the transaction.'),
      ('GET /api/checkouts/{identifier}/detail','Load saved quote/state and GET source orders/{id}.json for evidence.'),
      ('POST /refunds/prepare','Read original order and POST orders/{id}/refunds/calculate.json; verify totals; save prepared refund.'),
      ('POST /refunds/{refund_id}/complete','POST /terminal/refunds (electronic), then POST orders/{id}/refunds.json with tax/stock/transaction treatment.'),
      ('GET /reports/day-end or /api/reports','Read source orders.json and aggregate by the documented store/date basis.'),
      ('POST /api/reports/digest; GET /api/outbox','Create durable report message; show saved preview and delivery status. Scheduler can submit to configured SMTP.')
    ])+'''<p>Shopify paths use the supplied mock prefix <code>/admin/api/2026-10/</code>. The mock shapes are not a guarantee that the same adapter can be deployed unchanged against a live provider.</p></details>
    <details><summary>Plain-English glossary</summary>
    '''+table(['Term','Meaning'],[('API','A defined way for one program to request data or an action from another.'),('Mock','A local simulation of a provider used without live data or real money.'),('Variant','A sellable product option, such as a particular frame colour or lens configuration.'),('Rx','The wearer’s prescription.'),('Quote','The reviewed, saved amount before payment and source order creation.'),('Source of record','The system whose records finance and other systems treat as authoritative.'),('Idempotent result','Repeating the same completed operation returns its result instead of creating a second financial effect.'),('Reconciliation','Comparing recorded amounts and references to find differences.'),('Outbox','A durable queue of prepared messages and their delivery states.'),('Acceptance criterion','An observable outcome that tells us whether a piece of work is complete.')])+'''</details>
    <p class="muted">Evidence sources: candidate brief and stakeholder thread; current source code; README; STAKEHOLDER_REPLY.md; historical DECISIONS.md; docs/TEST_RESULTS.md; docs/EXERCISE_MUST_AUDIT.md; browser-run logs. Historical “planning only” statuses in DECISIONS.md are not treated as current implementation status.</p>
    '''))

