    js='''
    /** Apply ticket filters without changing the underlying documented status. */
    function filterTickets(){const term=document.querySelector('#ticket-search').value.toLowerCase().trim();const scope=document.querySelector('#ticket-filter').value;let count=0;document.querySelectorAll('[data-ticket]').forEach(ticket=>{ticket.hidden=!(ticket.textContent.toLowerCase().includes(term)&&(!scope||ticket.dataset.priority===scope));if(!ticket.hidden)count++;});document.querySelector('#ticket-count').textContent=count+' of 19 tickets shown.';}
    /** Expand every appendix and clear filters so printing preserves the complete brief. */
    function preparePrint(){document.querySelector('#ticket-search').value='';document.querySelector('#ticket-filter').value='';filterTickets();document.querySelectorAll('details').forEach(item=>item.open=true);}
    document.querySelector('#ticket-search').addEventListener('input',filterTickets);
    document.querySelector('#ticket-filter').addEventListener('change',filterTickets);
    document.querySelector('#expand-tickets').addEventListener('click',()=>{document.querySelectorAll('[data-ticket]:not([hidden])').forEach(item=>item.open=true);});
    document.querySelector('#print').addEventListener('click',()=>{preparePrint();window.print();});
    window.addEventListener('beforeprint',preparePrint);filterTickets();
    '''
